        '<ul><li><b>Gà</b>: lấy thịt, trứng.</li><li><b>Vịt, ngan, ngỗng</b>: thuỷ cầm, lấy thịt, trứng.</li></ul>',
        'Lợn, bò, trâu, dê là gia súc; cá, tôm là thuỷ sản — không phải gia cầm.',
